        int[] nums = parseIntArray(line.substring(0, sep));
        int k = Integer.parseInt(line.substring(sep + 1).trim());
        int n = nums.length;
        if (n == 0) {
            System.out.println("[]");
            return;
        }
        k %= n;
        if (k < 0) k += n;
        reverse(nums, 0, n - 1);
        reverse(nums, 0, k - 1);
        reverse(nums, k, n - 1);
        System.out.println(arrayToString(nums));
    }

    static void reverse(int[] a, int i, int j) {
        while (i < j) {
            int t = a[i];
            a[i] = a[j];
            a[j] = t;
            i++;
            j--;
